    import math
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        return {'mst_edges': [], 'total_weight': 0.0}
    # Build all mutual reachability edges
    edges = []
    for a, b, d in distances:
        w = max(core[a], core[b], d)
        # canonicalize endpoints: smaller first
        if a < b:
            edges.append((w, a, b))
        else:
            edges.append((w, b, a))
    # Sort by weight, then by first endpoint, then second endpoint
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True
    mst_edges = []
    total = 0.0
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected; cannot build MST')
    return {'mst_edges': mst_edges, 'total_weight': total}
